import type { ElementType } from "react";
import "./editorial-statement-hero.css";

export interface EditorialStatementHeroProps {
  title: string;
  summary: string;
  linkLabel: string;
  linkHref: string;
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
}

export function EditorialStatementHero({
  title,
  summary,
  linkLabel,
  linkHref,
  headingLevel = 1,
}: EditorialStatementHeroProps) {
  const Heading = `h${headingLevel}` as ElementType;

  return (
    <section className="tb-editorial-hero">
      <div className="tb-editorial-hero__frame">
        <Heading className="tb-editorial-hero__title">{title}</Heading>
        <div className="tb-editorial-hero__close">
          <p>{summary}</p>
          <a href={linkHref}>{linkLabel}</a>
        </div>
      </div>
    </section>
  );
}

.tb-editorial-hero {
  --tb-esh-paper: #f1f0ec;
  --tb-esh-ink: #1b1b1a;
  --tb-esh-accent: #1d5b46;
  container-type: inline-size;
  color: var(--tb-esh-ink);
  background: var(--tb-esh-paper);
}

.tb-editorial-hero,
.tb-editorial-hero * {
  box-sizing: border-box;
}

.tb-editorial-hero__frame {
  display: flex;
  min-height: 36rem;
  min-height: clamp(36rem, 68cqi, 52rem);
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(1.25rem, 3cqi, 3rem);
  border-top: 0.22rem solid currentColor;
}

.tb-editorial-hero__title {
  max-width: 78rem;
  margin: 0;
  font-size: clamp(3rem, 8vw, 9rem);
  font-size: clamp(3rem, 10cqi, 9rem);
  font-weight: 500;
  line-height: 0.93;
  letter-spacing: -0.04em;
  overflow-wrap: anywhere;
}

.tb-editorial-hero__close {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr));
  align-items: end;
  gap: 1.5rem 3rem;
  margin-top: clamp(3rem, 8cqi, 6rem);
}

.tb-editorial-hero__close p {
  max-width: 34rem;
  margin: 0;
  font-size: clamp(1.05rem, 2cqi, 1.45rem);
  line-height: 1.45;
}

.tb-editorial-hero__close a {
  width: fit-content;
  justify-self: end;
  color: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-decoration-thickness: 0.13em;
  text-underline-offset: 0.32em;
  transition: color 150ms ease-out;
}

.tb-editorial-hero__close a:hover {
  color: var(--tb-esh-accent);
}

.tb-editorial-hero__close a:focus-visible {
  outline: 3px solid var(--tb-esh-accent);
  outline-offset: 5px;
}

@container (min-width: 28rem) {
  .tb-editorial-hero__close a {
    white-space: nowrap;
  }
}

@container (max-width: 40rem) {
  .tb-editorial-hero__close a {
    justify-self: start;
  }
}

@media (max-width: 700px) {
  .tb-editorial-hero__close a {
    justify-self: start;
  }
}
